    body {
      margin: 0;
      padding: 0;
      font-family: 'IBM Plex Sans Arabic', 'Segoe UI', Tahoma, sans-serif;
      background: var(--bg);
      color: var(--text);
      font-size: 16px;
      line-height: 1.6;
    }

    :lang(ar) {
      letter-spacing: 0;
      font-size: 16px;
      line-height: 1.7;
    }

    .screen {
      max-width: 420px;
      margin: 0 auto;
      padding: 16px;
    }

    .header {
      display: flex;
      justify-content: space-between;
